-- Keep every role transition inside one Atlas statement; its ledger writer
-- always runs as the original migration login.
DO $management_authority_upgrade$
BEGIN
-- Explicit management authority. This migration confers no installation grant.
-- Checked deployment provisioning must create the dedicated owner/bootstrap roles.
DO $roles$
BEGIN
  IF (SELECT count(*) FROM pg_catalog.pg_roles
      WHERE rolname IN ('aegaeon_management_authority_owner','aegaeon_management_bootstrap')
        AND NOT (rolcanlogin OR rolsuper OR rolcreatedb OR rolcreaterole OR rolreplication OR rolbypassrls)) <> 2
  THEN
    RAISE EXCEPTION 'management authority requires checked role provisioning';
  END IF;
END
$roles$;

CREATE SCHEMA management_authority AUTHORIZATION aegaeon_management_authority_owner;
SET LOCAL ROLE aegaeon_management_authority_owner;
REVOKE ALL ON SCHEMA management_authority FROM PUBLIC;
DO $access$ BEGIN
  EXECUTE pg_catalog.format('GRANT USAGE ON SCHEMA management_authority TO %I',session_user);
END $access$;
RESET ROLE;
GRANT USAGE ON SCHEMA aegaeon TO aegaeon_management_authority_owner;
GRANT REFERENCES,SELECT ON aegaeon.administrators TO aegaeon_management_authority_owner;
GRANT SELECT ON aegaeon.teams,aegaeon.tenants,aegaeon.environments,
  aegaeon.end_users,aegaeon.runtime_management_sessions,aegaeon.api_keys,aegaeon.api_key_capabilities
  TO aegaeon_management_authority_owner;
SET LOCAL ROLE aegaeon_subject_owner;
GRANT SELECT ON aegaeon.application_organizations TO aegaeon_management_authority_owner;
RESET ROLE;

SET LOCAL ROLE aegaeon_management_authority_owner;
CREATE TABLE management_authority.installation (
  singleton boolean PRIMARY KEY DEFAULT true CHECK (singleton),
  id uuid NOT NULL UNIQUE DEFAULT pg_catalog.gen_random_uuid(),
  created_at timestamptz NOT NULL DEFAULT pg_catalog.clock_timestamp(),
  adopted_at timestamptz,
  cursor_key bytea NOT NULL CHECK (pg_catalog.octet_length(cursor_key)=32)
);
-- Resolve the installed extension instead of assuming its schema or relying on
-- search_path. Keep the generated key as data, without a default dependency that
-- would force unrelated core-only fingerprint readers to retain pgcrypto.
RESET ROLE;
DO $cursor_key$
DECLARE crypto_schema name; key_bytes bytea;
BEGIN
  SELECT n.nspname INTO STRICT crypto_schema FROM pg_catalog.pg_extension e
    JOIN pg_catalog.pg_namespace n ON n.oid=e.extnamespace WHERE e.extname='pgcrypto';
  EXECUTE pg_catalog.format('GRANT USAGE ON SCHEMA %I TO aegaeon_management_authority_owner',crypto_schema);
  SET LOCAL ROLE aegaeon_management_authority_owner;
  EXECUTE pg_catalog.format('SELECT %I.gen_random_bytes(32)',crypto_schema) INTO STRICT key_bytes;
  INSERT INTO management_authority.installation(singleton,cursor_key) VALUES(true,key_bytes);
END
$cursor_key$;
SET LOCAL ROLE aegaeon_management_authority_owner;

-- Membership in the bootstrap group alone is insufficient: deployment setup
-- explicitly binds one selected database and exact existing login identity.
CREATE TABLE management_authority.bootstrap_credentials (
  installation_id uuid NOT NULL REFERENCES management_authority.installation(id),
  role_oid oid NOT NULL,
  role_name name NOT NULL,
  enabled boolean NOT NULL DEFAULT true,
  PRIMARY KEY(installation_id,role_oid),
  UNIQUE(installation_id,role_name)
);

CREATE TABLE management_authority.principals (
  installation_id uuid NOT NULL REFERENCES management_authority.installation(id),
  administrator_id uuid NOT NULL REFERENCES aegaeon.administrators(id) ON DELETE RESTRICT,
  kind text NOT NULL CHECK (kind IN ('HUMAN','SERVICE')),
  incarnation uuid NOT NULL UNIQUE DEFAULT pg_catalog.gen_random_uuid(),
  PRIMARY KEY(installation_id,administrator_id),
  UNIQUE(installation_id,administrator_id,kind)
);

CREATE TABLE management_authority.action_registry (
  action_id text COLLATE "C" PRIMARY KEY,
  introduced_version integer NOT NULL CHECK (introduced_version > 0),
  resource_kind text NOT NULL CHECK (resource_kind IN ('user','team','tenant','environment','organization'))
);
INSERT INTO management_authority.action_registry VALUES
  ('inventory.users.read',1,'user'),
  ('inventory.teams.read',1,'team'),
  ('inventory.tenants.read',1,'tenant'),
  ('inventory.environments.read',1,'environment'),
  ('inventory.organizations.read',1,'organization');

CREATE TABLE management_authority.selectors (
  id uuid PRIMARY KEY,
  installation_id uuid NOT NULL REFERENCES management_authority.installation(id),
  mode text NOT NULL CHECK (mode IN ('exact','current_descendants','current_and_future_descendants')),
  anchor_kind text NOT NULL CHECK (anchor_kind IN ('installation','team','tenant','environment','user','organization')),
  anchor_id uuid NOT NULL,
  anchor_incarnation uuid NOT NULL,
  state text NOT NULL DEFAULT 'preparing' CHECK (state IN ('preparing','active','retired')),
  created_at timestamptz NOT NULL DEFAULT pg_catalog.clock_timestamp(),
  UNIQUE(id,installation_id),
  CHECK (mode='exact' OR anchor_kind NOT IN ('user','organization'))
);
CREATE TABLE management_authority.selector_members (
  selector_id uuid NOT NULL REFERENCES management_authority.selectors(id) ON DELETE RESTRICT,
  resource_kind text NOT NULL CHECK (resource_kind IN ('installation','team','tenant','environment','user','organization')),
  resource_id uuid NOT NULL,
  resource_incarnation uuid NOT NULL,
  PRIMARY KEY(selector_id,resource_kind,resource_id,resource_incarnation)
);

CREATE TABLE management_authority.operation_receipts (
  operation_id uuid PRIMARY KEY,
  installation_id uuid NOT NULL REFERENCES management_authority.installation(id),
  caller_role_oid oid NOT NULL,
  caller_role_name name NOT NULL,
  canonical_sha256 bytea NOT NULL CHECK (pg_catalog.octet_length(canonical_sha256)=32),
  result jsonb NOT NULL CHECK (pg_catalog.jsonb_typeof(result)='object' AND pg_catalog.octet_length(result::text)<=16384),
  created_at timestamptz NOT NULL DEFAULT pg_catalog.clock_timestamp()
);

CREATE TABLE management_authority.grants (
  id uuid PRIMARY KEY,
  installation_id uuid NOT NULL REFERENCES management_authority.installation(id),
  principal_id uuid NOT NULL,
  principal_kind text NOT NULL,
  parent_id uuid,
  captured_parent_epoch bigint,
  bootstrap_operation_id uuid REFERENCES management_authority.operation_receipts(operation_id) DEFERRABLE INITIALLY DEFERRED,
  use_selector_id uuid NOT NULL,
  use_action_policy text NOT NULL CHECK (use_action_policy IN ('enumerated','all_current_and_future')),
  use_actions text[] NOT NULL,
  delegation_selector_id uuid,
  delegation_action_policy text CHECK (delegation_action_policy IN ('enumerated','all_current_and_future')),
  delegation_actions text[] NOT NULL DEFAULT ARRAY[]::text[],
  acknowledged_registry_version integer NOT NULL CHECK (acknowledged_registry_version=1),
  conditions jsonb NOT NULL CHECK (pg_catalog.jsonb_typeof(conditions)='object' AND pg_catalog.octet_length(conditions::text)<=4096),
  valid_from timestamptz NOT NULL,
  expires_at timestamptz,
  permanent boolean NOT NULL,
  revision bigint NOT NULL DEFAULT 1 CHECK (revision>0),
  delegation_epoch bigint NOT NULL DEFAULT 1 CHECK (delegation_epoch>0),
  revoked_at timestamptz,
  label text NOT NULL DEFAULT '' CHECK (pg_catalog.octet_length(label)<=512),
  created_at timestamptz NOT NULL DEFAULT pg_catalog.clock_timestamp(),
  UNIQUE(id,installation_id),
  FOREIGN KEY(installation_id,principal_id,principal_kind)
    REFERENCES management_authority.principals(installation_id,administrator_id,kind),
  FOREIGN KEY(parent_id,installation_id) REFERENCES management_authority.grants(id,installation_id),
  FOREIGN KEY(use_selector_id,installation_id) REFERENCES management_authority.selectors(id,installation_id),
  FOREIGN KEY(delegation_selector_id,installation_id) REFERENCES management_authority.selectors(id,installation_id),
  CHECK ((parent_id IS NULL AND captured_parent_epoch IS NULL AND bootstrap_operation_id IS NOT NULL)
    OR (parent_id IS NOT NULL AND parent_id<>id AND captured_parent_epoch IS NOT NULL AND captured_parent_epoch>0 AND bootstrap_operation_id IS NULL)),
  CHECK (pg_catalog.isfinite(valid_from) AND (expires_at IS NULL OR pg_catalog.isfinite(expires_at))),
  CHECK ((permanent AND expires_at IS NULL) OR (NOT permanent AND expires_at IS NOT NULL AND expires_at>valid_from)),
  CHECK ((use_action_policy='enumerated' AND pg_catalog.cardinality(use_actions) BETWEEN 1 AND 5)
    OR (use_action_policy='all_current_and_future' AND pg_catalog.cardinality(use_actions)=0)),
  CHECK ((delegation_selector_id IS NULL)=(delegation_action_policy IS NULL)),
  CHECK ((delegation_selector_id IS NULL AND delegation_action_policy IS NULL AND pg_catalog.cardinality(delegation_actions)=0)
    OR (delegation_selector_id IS NOT NULL AND delegation_action_policy='enumerated' AND pg_catalog.cardinality(delegation_actions) BETWEEN 1 AND 5)
    OR (delegation_selector_id IS NOT NULL AND delegation_action_policy='all_current_and_future' AND pg_catalog.cardinality(delegation_actions)=0))
);
CREATE INDEX management_grants_principal_idx
  ON management_authority.grants(installation_id,principal_id,principal_kind,id)
  WHERE revoked_at IS NULL;
CREATE UNIQUE INDEX management_grants_bootstrap_idx ON management_authority.grants(bootstrap_operation_id) WHERE bootstrap_operation_id IS NOT NULL;
CREATE INDEX management_grants_parent_idx ON management_authority.grants(parent_id) WHERE parent_id IS NOT NULL;

CREATE TABLE management_authority.audit_events (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  installation_id uuid NOT NULL REFERENCES management_authority.installation(id),
  operation_id uuid NOT NULL REFERENCES management_authority.operation_receipts(operation_id) DEFERRABLE INITIALLY DEFERRED,
  grant_id uuid NOT NULL REFERENCES management_authority.grants(id),
  actor_role_name name NOT NULL,
  event_type text NOT NULL CHECK (event_type IN ('root_grant_issued','grant_delegated','grant_restricted','grant_revoked','grant_metadata_updated')),
  revision bigint NOT NULL CHECK (revision>0),
  delegation_epoch bigint NOT NULL CHECK (delegation_epoch>0),
  acknowledged_registry_version integer NOT NULL,
  occurred_at timestamptz NOT NULL DEFAULT pg_catalog.clock_timestamp()
);
CREATE INDEX management_grants_audit_idx ON management_authority.audit_events(installation_id,id);

REVOKE ALL ON ALL TABLES IN SCHEMA management_authority FROM PUBLIC;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA management_authority FROM PUBLIC;

CREATE FUNCTION management_authority.protect_grant_v1() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,management_authority,pg_temp
AS $function$
DECLARE authority_changed boolean; parent management_authority.grants; ancestor management_authority.grants;
  selected_parent uuid; visited uuid[]; depth integer:=0;
BEGIN
  IF TG_OP='INSERT' THEN
    IF NEW.parent_id IS NULL THEN RETURN NEW; END IF;
    SELECT * INTO parent FROM management_authority.grants WHERE id=NEW.parent_id AND installation_id=NEW.installation_id FOR SHARE;
    IF NOT FOUND OR parent.revoked_at IS NOT NULL OR parent.delegation_epoch<>NEW.captured_parent_epoch
      OR parent.delegation_selector_id IS NULL
      OR NEW.valid_from<parent.valid_from
      OR (NOT parent.permanent AND (NEW.permanent OR NEW.expires_at>parent.expires_at))
      OR NOT management_authority.action_contains_v1(parent.delegation_action_policy,parent.delegation_actions,NEW.use_action_policy,NEW.use_actions)
      OR NOT management_authority.selector_contains_v1(parent.delegation_selector_id,NEW.use_selector_id,NEW.installation_id)
      OR (NEW.delegation_selector_id IS NOT NULL AND
        (NOT management_authority.action_contains_v1(parent.delegation_action_policy,parent.delegation_actions,NEW.delegation_action_policy,NEW.delegation_actions)
         OR NOT management_authority.selector_contains_v1(parent.delegation_selector_id,NEW.delegation_selector_id,NEW.installation_id)))
      OR NOT management_authority.conditions_contain_v1(parent.conditions,NEW.conditions)
    THEN RAISE EXCEPTION 'one complete parent delegation envelope is required' USING ERRCODE='23514'; END IF;
    selected_parent:=NEW.parent_id; visited:=ARRAY[NEW.id];
    LOOP
      depth:=depth+1;
      IF depth>8 OR selected_parent=ANY(visited) THEN RAISE EXCEPTION 'delegation cycle or depth limit' USING ERRCODE='23514'; END IF;
      SELECT * INTO ancestor FROM management_authority.grants WHERE id=selected_parent AND installation_id=NEW.installation_id FOR SHARE;
      IF NOT FOUND OR ancestor.revoked_at IS NOT NULL THEN RAISE EXCEPTION 'live delegation ancestry required' USING ERRCODE='23514'; END IF;
      visited:=visited||ancestor.id;
      IF ancestor.parent_id IS NULL THEN EXIT; END IF;
      IF NOT EXISTS(SELECT FROM management_authority.grants g WHERE g.id=ancestor.parent_id AND g.installation_id=NEW.installation_id
        AND g.delegation_epoch=ancestor.captured_parent_epoch) THEN RAISE EXCEPTION 'stale delegation ancestry' USING ERRCODE='23514'; END IF;
      selected_parent:=ancestor.parent_id;
    END LOOP;
    RETURN NEW;
  END IF;
  IF TG_OP='DELETE' THEN
    RAISE EXCEPTION 'management grant history is retained' USING ERRCODE='23514';
  END IF;
  IF (NEW.id,NEW.installation_id,NEW.principal_id,NEW.principal_kind,
      NEW.parent_id,NEW.captured_parent_epoch,NEW.bootstrap_operation_id,NEW.created_at)
      IS DISTINCT FROM
     (OLD.id,OLD.installation_id,OLD.principal_id,OLD.principal_kind,
      OLD.parent_id,OLD.captured_parent_epoch,OLD.bootstrap_operation_id,OLD.created_at)
  THEN
    RAISE EXCEPTION 'management grant identity and parent basis are immutable' USING ERRCODE='23514';
  END IF;
  IF OLD.revoked_at IS NOT NULL AND NEW.revoked_at IS DISTINCT FROM OLD.revoked_at THEN
    RAISE EXCEPTION 'management grant revocation is terminal' USING ERRCODE='23514';
  END IF;
  authority_changed :=
    (NEW.use_selector_id,NEW.use_action_policy,NEW.use_actions,
     NEW.delegation_selector_id,NEW.delegation_action_policy,NEW.delegation_actions,
     NEW.acknowledged_registry_version,NEW.conditions,NEW.valid_from,NEW.expires_at,NEW.permanent,NEW.revoked_at)
    IS DISTINCT FROM
    (OLD.use_selector_id,OLD.use_action_policy,OLD.use_actions,
     OLD.delegation_selector_id,OLD.delegation_action_policy,OLD.delegation_actions,
     OLD.acknowledged_registry_version,OLD.conditions,OLD.valid_from,OLD.expires_at,OLD.permanent,OLD.revoked_at);
  IF NEW.revision<>OLD.revision+1
     OR NEW.delegation_epoch<>OLD.delegation_epoch+(CASE WHEN authority_changed THEN 1 ELSE 0 END) THEN
    RAISE EXCEPTION 'management grant revision or delegation epoch mismatch' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END
$function$;
CREATE TRIGGER management_grant_identity BEFORE INSERT OR UPDATE OR DELETE ON management_authority.grants
FOR EACH ROW EXECUTE FUNCTION management_authority.protect_grant_v1();

CREATE FUNCTION management_authority.protect_selector_v1() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,management_authority,pg_temp
AS $function$
BEGIN
  IF TG_OP='DELETE' THEN
    RAISE EXCEPTION 'management selector history is retained' USING ERRCODE='23514';
  END IF;
  IF (NEW.id,NEW.installation_id,NEW.mode,NEW.anchor_kind,NEW.anchor_id,NEW.anchor_incarnation,NEW.created_at)
     IS DISTINCT FROM
     (OLD.id,OLD.installation_id,OLD.mode,OLD.anchor_kind,OLD.anchor_id,OLD.anchor_incarnation,OLD.created_at)
     OR NOT ((OLD.state='preparing' AND NEW.state IN ('active','retired'))
         OR (OLD.state='active' AND NEW.state='retired'))
  THEN
    RAISE EXCEPTION 'management selector identity or terminal state mismatch' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END
$function$;
CREATE TRIGGER management_selector_identity BEFORE UPDATE OR DELETE ON management_authority.selectors
FOR EACH ROW EXECUTE FUNCTION management_authority.protect_selector_v1();

CREATE FUNCTION management_authority.protect_selector_member_v1() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,management_authority,pg_temp
AS $function$
DECLARE selector uuid;
BEGIN
  IF TG_OP='UPDATE' THEN
    RAISE EXCEPTION 'selector member identities are immutable' USING ERRCODE='23514';
  END IF;
  selector := CASE WHEN TG_OP='DELETE' THEN OLD.selector_id ELSE NEW.selector_id END;
  -- The same row lock serializes membership preparation with activation.
  IF NOT EXISTS(SELECT FROM management_authority.selectors WHERE id=selector AND state='preparing' FOR UPDATE) THEN
    RAISE EXCEPTION 'selector membership is closed' USING ERRCODE='23514';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END
$function$;
CREATE TRIGGER management_selector_member_identity BEFORE INSERT OR UPDATE OR DELETE ON management_authority.selector_members
FOR EACH ROW EXECUTE FUNCTION management_authority.protect_selector_member_v1();

CREATE FUNCTION management_authority.retain_history_v1() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,management_authority,pg_temp
AS $function$
BEGIN
  RAISE EXCEPTION 'management authority history is immutable' USING ERRCODE='23514';
END
$function$;
CREATE TRIGGER management_principal_identity BEFORE UPDATE OR DELETE ON management_authority.principals
FOR EACH ROW EXECUTE FUNCTION management_authority.retain_history_v1();
CREATE TRIGGER management_operation_receipt_identity BEFORE UPDATE OR DELETE ON management_authority.operation_receipts
FOR EACH ROW EXECUTE FUNCTION management_authority.retain_history_v1();
CREATE TRIGGER management_audit_identity BEFORE UPDATE OR DELETE ON management_authority.audit_events
FOR EACH ROW EXECUTE FUNCTION management_authority.retain_history_v1();


-- Incarnations live outside product rows so a subject/Organization snapshot does
-- not import management authority. Recreating a deleted UUID gets a new identity.
CREATE TABLE management_authority.resource_identities (
  installation_id uuid NOT NULL REFERENCES management_authority.installation(id),
  resource_kind text NOT NULL CHECK (resource_kind IN ('team','tenant','environment','user','organization')),
  resource_id uuid NOT NULL,
  incarnation uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),
  live boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT pg_catalog.clock_timestamp()
);
CREATE UNIQUE INDEX management_resource_live_identity
  ON management_authority.resource_identities(installation_id,resource_kind,resource_id) WHERE live;

INSERT INTO management_authority.resource_identities(installation_id,resource_kind,resource_id)
SELECT i.id,resource.kind,resource.id FROM management_authority.installation i
CROSS JOIN (
  SELECT 'team' kind,id FROM aegaeon.teams UNION ALL
  SELECT 'tenant',id FROM aegaeon.tenants UNION ALL
  SELECT 'environment',id FROM aegaeon.environments UNION ALL
  SELECT 'user',id FROM aegaeon.end_users UNION ALL
  SELECT 'organization',id FROM aegaeon.application_organizations
) resource;

CREATE FUNCTION management_authority.protect_resource_history_v1() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,management_authority,pg_temp
AS $function$
BEGIN
  IF TG_OP='UPDATE' AND OLD.live AND NOT NEW.live
    AND (NEW.installation_id,NEW.resource_kind,NEW.resource_id,NEW.incarnation,NEW.created_at)
       IS NOT DISTINCT FROM
        (OLD.installation_id,OLD.resource_kind,OLD.resource_id,OLD.incarnation,OLD.created_at)
  THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'resource incarnations are immutable and retirement is terminal' USING ERRCODE='23514';
END
$function$;
CREATE TRIGGER management_resource_history BEFORE UPDATE OR DELETE ON management_authority.resource_identities
FOR EACH ROW EXECUTE FUNCTION management_authority.protect_resource_history_v1();

CREATE FUNCTION management_authority.capture_resource_identity_v1() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,management_authority,pg_temp
AS $function$
DECLARE selected_installation uuid;
BEGIN
  SELECT id INTO STRICT selected_installation FROM management_authority.installation;
  IF TG_OP='INSERT' THEN
    INSERT INTO management_authority.resource_identities(installation_id,resource_kind,resource_id)
      VALUES(selected_installation,TG_ARGV[0],NEW.id);
    RETURN NEW;
  ELSIF TG_OP='DELETE' THEN
    UPDATE management_authority.resource_identities SET live=false
      WHERE installation_id=selected_installation AND resource_kind=TG_ARGV[0] AND resource_id=OLD.id AND live;
    IF NOT FOUND THEN RAISE EXCEPTION 'resource identity is missing' USING ERRCODE='23514'; END IF;
    RETURN OLD;
  ELSIF NEW.id IS DISTINCT FROM OLD.id THEN
    RAISE EXCEPTION 'management resource identity cannot be reassigned' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END
$function$;

CREATE FUNCTION management_authority.protect_administrator_identity_v1() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,management_authority,pg_temp
AS $function$
BEGIN
  IF (NEW.id,NEW.kind) IS DISTINCT FROM (OLD.id,OLD.kind) THEN
    RAISE EXCEPTION 'management principal identity and kind are immutable' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END
$function$;

CREATE FUNCTION management_authority.protect_installation_v1() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,management_authority,pg_temp
AS $function$
BEGIN
  IF TG_OP='UPDATE' AND OLD.adopted_at IS NULL AND NEW.adopted_at IS NOT NULL
    AND pg_catalog.isfinite(NEW.adopted_at)
    AND (NEW.singleton,NEW.id,NEW.created_at,NEW.cursor_key) IS NOT DISTINCT FROM (OLD.singleton,OLD.id,OLD.created_at,OLD.cursor_key)
  THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'installation identity and adoption are immutable' USING ERRCODE='23514';
END
$function$;
CREATE TRIGGER management_installation_identity BEFORE UPDATE OR DELETE ON management_authority.installation
FOR EACH ROW EXECUTE FUNCTION management_authority.protect_installation_v1();

CREATE FUNCTION management_authority.inventory_text_v1(value text,maximum_bytes integer) RETURNS text
LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,pg_temp
AS $function$
BEGIN
  IF maximum_bytes NOT BETWEEN 1 AND 2048 OR pg_catalog.octet_length(value)>maximum_bytes THEN
    RAISE EXCEPTION 'stored inventory text exceeds the response bound' USING ERRCODE='23514';
  END IF;
  RETURN value;
END
$function$;

-- Only selected non-credential fields enter the inventory projection.
CREATE VIEW management_authority.current_resources AS
SELECT i.id installation_id,'installation'::text resource_kind,i.id resource_id,i.id incarnation,
  NULL::text parent_kind,NULL::uuid parent_id,
  pg_catalog.jsonb_build_object('id',i.id) document
FROM management_authority.installation i
UNION ALL
SELECT r.installation_id,'team',t.id,r.incarnation,'installation',r.installation_id,
  pg_catalog.jsonb_build_object('id',t.id,'name',management_authority.inventory_text_v1(t.name,1024),'status',t.status)
FROM aegaeon.teams t JOIN management_authority.resource_identities r
  ON r.resource_kind='team' AND r.resource_id=t.id AND r.live WHERE t.deleted_at IS NULL
UNION ALL
SELECT r.installation_id,'tenant',t.id,r.incarnation,'team',t.team_id,
  pg_catalog.jsonb_build_object('id',t.id,'teamId',t.team_id,'name',management_authority.inventory_text_v1(t.name,1024),'status',t.status)
FROM aegaeon.tenants t JOIN management_authority.resource_identities r
  ON r.resource_kind='tenant' AND r.resource_id=t.id AND r.live WHERE t.deleted_at IS NULL
UNION ALL
SELECT r.installation_id,'environment',e.id,r.incarnation,'tenant',e.tenant_id,
  pg_catalog.jsonb_build_object('id',e.id,'tenantId',e.tenant_id,'name',management_authority.inventory_text_v1(e.name,1024),'issuer',management_authority.inventory_text_v1(e.issuer_url,2048),'status',e.status)
FROM aegaeon.environments e JOIN management_authority.resource_identities r
  ON r.resource_kind='environment' AND r.resource_id=e.id AND r.live WHERE e.deleted_at IS NULL
UNION ALL
SELECT r.installation_id,'user',u.id,r.incarnation,'environment',u.environment_id,
  pg_catalog.jsonb_build_object('id',u.id,'environmentId',u.environment_id,'subject',management_authority.inventory_text_v1(u.subject,512),'status',u.status)
FROM aegaeon.end_users u JOIN management_authority.resource_identities r
  ON r.resource_kind='user' AND r.resource_id=u.id AND r.live
UNION ALL
SELECT r.installation_id,'organization',o.id,r.incarnation,'environment',o.environment_id,
  pg_catalog.jsonb_build_object('id',o.id,'environmentId',o.environment_id,'domainId',o.domain_id,'externalId',management_authority.inventory_text_v1(o.external_id,256),'state',o.state)
FROM aegaeon.application_organizations o JOIN management_authority.resource_identities r
  ON r.resource_kind='organization' AND r.resource_id=o.id AND r.live WHERE o.state<>'deleted';

CREATE FUNCTION management_authority.selector_covers_v1(
  selected_selector uuid,selected_installation uuid,selected_kind text,selected_resource uuid
) RETURNS boolean
LANGUAGE sql STABLE SET search_path=pg_catalog,management_authority,pg_temp
AS $function$
WITH RECURSIVE path AS (
  SELECT r.*,0 depth FROM management_authority.current_resources r
    WHERE r.installation_id=selected_installation AND r.resource_kind=selected_kind AND r.resource_id=selected_resource
  UNION ALL
  SELECT r.*,p.depth+1 FROM path p JOIN management_authority.current_resources r
    ON r.installation_id=p.installation_id AND r.resource_kind=p.parent_kind AND r.resource_id=p.parent_id
    WHERE p.depth<4
)
SELECT EXISTS(
  SELECT FROM management_authority.selectors s JOIN path anchor
    ON anchor.resource_kind=s.anchor_kind AND anchor.resource_id=s.anchor_id AND anchor.incarnation=s.anchor_incarnation
  WHERE s.id=selected_selector AND s.installation_id=selected_installation AND s.state='active'
    AND EXISTS(SELECT FROM path WHERE resource_kind='installation' AND resource_id=selected_installation)
    AND (s.mode='current_and_future_descendants'
      OR (s.mode='exact' AND anchor.depth=0)
      OR (s.mode='current_descendants' AND EXISTS(
        SELECT FROM path leaf JOIN management_authority.selector_members member
          ON member.selector_id=s.id AND member.resource_kind=leaf.resource_kind
            AND member.resource_id=leaf.resource_id AND member.resource_incarnation=leaf.incarnation
        WHERE leaf.depth=0)))
);
$function$;

GRANT USAGE ON SCHEMA management_authority TO aegaeon_subject_owner;
GRANT EXECUTE ON FUNCTION management_authority.capture_resource_identity_v1() TO aegaeon_subject_owner;
-- Conditions use a closed schema. Unknown keys and malformed evidence deny;
-- neither JSON truthiness nor an omitted expiry produces permanent authentication.
CREATE FUNCTION management_authority.conditions_hold_v1(
  conditions jsonb,authentication jsonb,checked_at timestamptz
) RETURNS boolean
LANGUAGE plpgsql STABLE SET search_path=pg_catalog,management_authority,pg_temp
AS $function$
DECLARE authenticated_at timestamptz; expires_at timestamptz; maximum_age bigint;
BEGIN
  IF pg_catalog.jsonb_typeof(conditions) IS DISTINCT FROM 'object'
    OR EXISTS(SELECT FROM pg_catalog.jsonb_object_keys(conditions) key
      WHERE key NOT IN ('credential_kind','credential_id','maximum_authentication_age_seconds'))
    OR authentication->>'principal_kind' NOT IN ('HUMAN','SERVICE')
    OR (authentication->>'principal_id')::uuid IS NULL
    OR (authentication->>'credential_id')::uuid IS NULL
  THEN RETURN false; END IF;
  authenticated_at := (authentication->>'authenticated_at')::timestamptz;
  expires_at := (authentication->>'expires_at')::timestamptz;
  IF authenticated_at IS NULL OR expires_at IS NULL OR NOT pg_catalog.isfinite(authenticated_at)
    OR NOT pg_catalog.isfinite(expires_at) OR authenticated_at>checked_at OR expires_at<=checked_at
    OR expires_at<=authenticated_at THEN RETURN false; END IF;
  IF conditions ? 'credential_kind' AND
    (pg_catalog.jsonb_typeof(conditions->'credential_kind')<>'string'
     OR conditions->>'credential_kind' IS DISTINCT FROM authentication->>'principal_kind')
    THEN RETURN false; END IF;
  IF conditions ? 'credential_id' AND
    (pg_catalog.jsonb_typeof(conditions->'credential_id')<>'string'
     OR (conditions->>'credential_id')::uuid IS DISTINCT FROM (authentication->>'credential_id')::uuid)
    THEN RETURN false; END IF;
  IF conditions ? 'maximum_authentication_age_seconds' THEN
    IF pg_catalog.jsonb_typeof(conditions->'maximum_authentication_age_seconds')<>'number'
      OR (conditions->>'maximum_authentication_age_seconds') !~ '^[0-9]{1,10}$'
      THEN RETURN false; END IF;
    maximum_age := (conditions->>'maximum_authentication_age_seconds')::bigint;
    IF maximum_age>2147483647 OR checked_at-authenticated_at>pg_catalog.make_interval(secs=>maximum_age::double precision)
      THEN RETURN false; END IF;
  END IF;
  RETURN true;
EXCEPTION WHEN invalid_text_representation OR datetime_field_overflow OR numeric_value_out_of_range THEN
  RETURN false;
END
$function$;

CREATE FUNCTION management_authority.action_covers_v1(policy text,actions text[],selected_action text)
RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog,management_authority,pg_temp
AS $function$
SELECT EXISTS(SELECT FROM management_authority.action_registry WHERE action_id=selected_action)
  AND (policy='all_current_and_future' OR (policy='enumerated' AND selected_action=ANY(actions)));
$function$;

-- Complete, current leaf-to-root chain. A ninth delegation edge, cycle, absent
-- root, stale parent epoch, disabled principal or changed condition rejects all.
CREATE FUNCTION management_authority.validated_chain_v1(
  selected_grant uuid,selected_installation uuid,authentication jsonb,checked_at timestamptz
) RETURNS TABLE(grant_id uuid,depth integer,selector_id uuid,action_policy text,actions text[],revision bigint,delegation_epoch bigint)
LANGUAGE plpgsql STABLE SET search_path=pg_catalog,management_authority,pg_temp
AS $function$
DECLARE node management_authority.grants; current_id uuid:=selected_grant;
  visited uuid[]:=ARRAY[]::uuid[]; expected_epoch bigint; position integer:=0;
BEGIN
  LOOP
    IF position>8 OR current_id=ANY(visited) THEN RETURN; END IF;
    SELECT * INTO node FROM management_authority.grants g WHERE g.id=current_id AND g.installation_id=selected_installation;
    IF NOT FOUND OR node.revoked_at IS NOT NULL OR node.valid_from>checked_at
      OR (NOT node.permanent AND node.expires_at<=checked_at)
      OR (expected_epoch IS NOT NULL AND expected_epoch<>node.delegation_epoch)
      OR NOT management_authority.conditions_hold_v1(node.conditions,authentication,checked_at)
      OR NOT EXISTS(SELECT FROM aegaeon.administrators a WHERE a.id=node.principal_id AND a.kind::text=node.principal_kind AND a.status='ACTIVE')
      OR (position=0 AND (node.principal_id IS DISTINCT FROM (authentication->>'principal_id')::uuid
                         OR node.principal_kind IS DISTINCT FROM authentication->>'principal_kind'))
      OR (position>0 AND node.delegation_selector_id IS NULL)
    THEN RETURN; END IF;
    visited:=visited||current_id;
    IF node.parent_id IS NULL THEN
      IF node.bootstrap_operation_id IS NULL OR NOT EXISTS(
        SELECT FROM management_authority.operation_receipts r
        WHERE r.operation_id=node.bootstrap_operation_id AND r.installation_id=selected_installation)
        THEN RETURN; END IF;
      EXIT;
    END IF;
    current_id:=node.parent_id; expected_epoch:=node.captured_parent_epoch; position:=position+1;
  END LOOP;
  -- No rows have been returned before validating the root and every ancestor.
  RETURN QUERY SELECT g.id,(v.ordinality-1)::integer,
    CASE WHEN v.ordinality=1 THEN g.use_selector_id ELSE g.delegation_selector_id END,
    CASE WHEN v.ordinality=1 THEN g.use_action_policy ELSE g.delegation_action_policy END,
    CASE WHEN v.ordinality=1 THEN g.use_actions ELSE g.delegation_actions END,g.revision,g.delegation_epoch
    FROM pg_catalog.unnest(visited) WITH ORDINALITY v(id,ordinality)
      JOIN management_authority.grants g ON g.id=v.id ORDER BY v.ordinality;
EXCEPTION WHEN invalid_text_representation OR datetime_field_overflow OR numeric_value_out_of_range THEN
  RETURN;
END
$function$;

CREATE FUNCTION management_authority.grant_covers_v1(
  selected_grant uuid,selected_installation uuid,authentication jsonb,selected_action text,
  selected_kind text,selected_resource uuid,checked_at timestamptz
) RETURNS boolean
LANGUAGE sql STABLE SET search_path=pg_catalog,management_authority,pg_temp
AS $function$
SELECT EXISTS(SELECT FROM management_authority.action_registry WHERE action_id=selected_action AND resource_kind=selected_kind)
  AND coalesce((SELECT pg_catalog.bool_and(
    management_authority.action_covers_v1(c.action_policy,c.actions,selected_action)
    AND management_authority.selector_covers_v1(c.selector_id,selected_installation,selected_kind,selected_resource))
    FROM management_authority.validated_chain_v1(selected_grant,selected_installation,authentication,checked_at) c),false);
$function$;

CREATE FUNCTION management_authority.action_contains_v1(parent_policy text,parent_actions text[],child_policy text,child_actions text[])
RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog,management_authority,pg_temp
AS $function$
SELECT NOT EXISTS(SELECT FROM pg_catalog.unnest(child_actions) child
    WHERE NOT EXISTS(SELECT FROM management_authority.action_registry WHERE action_id=child))
  AND (parent_policy='all_current_and_future'
    OR (parent_policy='enumerated' AND child_policy='enumerated' AND child_actions<@parent_actions));
$function$;

CREATE FUNCTION management_authority.conditions_contain_v1(parent_conditions jsonb,child_conditions jsonb)
RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,pg_temp
AS $function$
SELECT NOT EXISTS(SELECT FROM pg_catalog.jsonb_each(parent_conditions) condition
  WHERE CASE condition.key WHEN 'maximum_authentication_age_seconds' THEN
    NOT child_conditions ? condition.key OR (child_conditions->>condition.key)::bigint>(condition.value#>>'{}')::bigint
  ELSE child_conditions->condition.key IS DISTINCT FROM condition.value END);
$function$;

CREATE FUNCTION management_authority.selector_contains_v1(parent_selector uuid,child_selector uuid,selected_installation uuid)
RETURNS boolean LANGUAGE plpgsql STABLE SET search_path=pg_catalog,management_authority,pg_temp
AS $function$
DECLARE parent management_authority.selectors; child management_authority.selectors;
BEGIN
  SELECT * INTO parent FROM management_authority.selectors WHERE id=parent_selector AND installation_id=selected_installation AND state='active';
  IF NOT FOUND THEN RETURN false; END IF;
  SELECT * INTO child FROM management_authority.selectors WHERE id=child_selector AND installation_id=selected_installation AND state='active';
  IF NOT FOUND OR NOT management_authority.selector_covers_v1(parent.id,selected_installation,child.anchor_kind,child.anchor_id)
    THEN RETURN false; END IF;
  IF child.mode='exact' OR parent.mode='current_and_future_descendants' THEN RETURN true; END IF;
  IF child.mode='current_and_future_descendants' THEN RETURN false; END IF;
  RETURN NOT EXISTS(SELECT FROM management_authority.selector_members m WHERE m.selector_id=child.id
    AND management_authority.selector_covers_v1(child.id,selected_installation,m.resource_kind,m.resource_id)
    AND NOT management_authority.selector_covers_v1(parent.id,selected_installation,m.resource_kind,m.resource_id));
END
$function$;

CREATE FUNCTION management_authority.checked_actions_v1(specification jsonb) RETURNS text[]
LANGUAGE plpgsql STABLE SET search_path=pg_catalog,management_authority,pg_temp
AS $function$
DECLARE actions text[];
BEGIN
  IF pg_catalog.jsonb_typeof(specification) IS DISTINCT FROM 'object'
    OR EXISTS(SELECT FROM pg_catalog.jsonb_object_keys(specification) key WHERE key NOT IN ('policy','actions','registry_version'))
    OR specification->'registry_version' IS DISTINCT FROM '1'::jsonb
    OR coalesce(specification->>'policy','') NOT IN ('enumerated','all_current_and_future')
    OR pg_catalog.jsonb_typeof(specification->'actions') IS DISTINCT FROM 'array'
    OR EXISTS(SELECT FROM pg_catalog.jsonb_array_elements(specification->'actions') action WHERE pg_catalog.jsonb_typeof(action)<>'string')
  THEN RAISE EXCEPTION 'invalid management action policy' USING ERRCODE='22023'; END IF;
  SELECT coalesce(pg_catalog.array_agg(action ORDER BY action COLLATE "C"),ARRAY[]::text[])
    INTO actions FROM pg_catalog.jsonb_array_elements_text(specification->'actions') action;
  IF (specification->>'policy'='enumerated' AND (pg_catalog.cardinality(actions) NOT BETWEEN 1 AND 5
        OR pg_catalog.cardinality(actions)<>(SELECT count(DISTINCT a) FROM pg_catalog.unnest(actions) a)
        OR EXISTS(SELECT FROM pg_catalog.unnest(actions) a WHERE NOT EXISTS(SELECT FROM management_authority.action_registry WHERE action_id=a))))
    OR (specification->>'policy'='all_current_and_future' AND pg_catalog.cardinality(actions)<>0)
  THEN RAISE EXCEPTION 'unregistered, duplicate or unbounded management action selection' USING ERRCODE='22023'; END IF;
  RETURN actions;
END
$function$;

-- Called only inside the dedicated bootstrap/delegation transaction. Snapshot
-- construction is bounded to 100,000 resources and remains inactive until the
-- complete membership set is inserted. There is no partially active grant.
CREATE FUNCTION management_authority.prepare_selector_v1(selected_installation uuid,specification jsonb) RETURNS uuid
LANGUAGE plpgsql SET search_path=pg_catalog,management_authority,pg_temp
AS $function$
DECLARE selector uuid; anchor management_authority.current_resources; prepared bigint;
BEGIN
  IF pg_catalog.current_setting('transaction_isolation') NOT IN ('repeatable read','serializable')
    OR pg_catalog.jsonb_typeof(specification) IS DISTINCT FROM 'object'
    OR EXISTS(SELECT FROM pg_catalog.jsonb_object_keys(specification) key WHERE key NOT IN ('id','mode','anchor_kind','anchor_id'))
    OR coalesce(specification->>'mode','') NOT IN ('exact','current_descendants','current_and_future_descendants')
    THEN RAISE EXCEPTION 'invalid selector or missing consistent transaction' USING ERRCODE='22023'; END IF;
  selector:=(specification->>'id')::uuid;
  IF selector IS NULL OR selector='00000000-0000-0000-0000-000000000000' THEN
    RAISE EXCEPTION 'explicit selector identity required' USING ERRCODE='22023'; END IF;
  SELECT * INTO anchor FROM management_authority.current_resources
    WHERE installation_id=selected_installation AND resource_kind=specification->>'anchor_kind'
      AND resource_id=(specification->>'anchor_id')::uuid;
  IF NOT FOUND THEN RAISE EXCEPTION 'selector anchor is unavailable' USING ERRCODE='22023'; END IF;
  INSERT INTO management_authority.selectors(id,installation_id,mode,anchor_kind,anchor_id,anchor_incarnation)
  VALUES(selector,selected_installation,specification->>'mode',anchor.resource_kind,anchor.resource_id,anchor.incarnation);
  IF specification->>'mode'='current_descendants' THEN
    WITH RECURSIVE descendants AS (
      SELECT anchor.resource_kind,anchor.resource_id,anchor.incarnation,0 depth
      UNION ALL
      SELECT r.resource_kind,r.resource_id,r.incarnation,d.depth+1
      FROM descendants d JOIN management_authority.current_resources r
        ON r.installation_id=selected_installation AND r.parent_kind=d.resource_kind AND r.parent_id=d.resource_id
      WHERE d.depth<4
    ) INSERT INTO management_authority.selector_members(selector_id,resource_kind,resource_id,resource_incarnation)
      SELECT selector,resource_kind,resource_id,incarnation FROM descendants LIMIT 100001;
    GET DIAGNOSTICS prepared=ROW_COUNT;
    IF prepared>100000 THEN RAISE EXCEPTION 'selector snapshot exceeds bounded preparation limit' USING ERRCODE='54000'; END IF;
  END IF;
  UPDATE management_authority.selectors SET state='active' WHERE id=selector;
  RETURN selector;
END
$function$;

CREATE FUNCTION management_authority.bootstrap_v1(request jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,management_authority,pg_temp
SET lock_timeout='5s' SET work_mem='4MB'
AS $function$
DECLARE installation uuid; operation uuid; grant_identity uuid; principal uuid; principal_kind text;
  request_hash bytea; receipt management_authority.operation_receipts; caller_oid oid;
  use_selector uuid; delegation_selector uuid; use_actions text[]; delegation_actions text[]:=ARRAY[]::text[];
  starts timestamptz; ends timestamptz; forever boolean; conditions jsonb; result jsonb;
BEGIN
  IF pg_catalog.current_setting('transaction_isolation') NOT IN ('repeatable read','serializable')
    OR pg_catalog.current_setting('statement_timeout')::interval NOT BETWEEN interval '1 millisecond' AND interval '30 seconds'
    OR pg_catalog.jsonb_typeof(request) IS DISTINCT FROM 'object' OR pg_catalog.octet_length(request::text)>16384
    OR EXISTS(SELECT FROM pg_catalog.jsonb_object_keys(request) key WHERE key NOT IN
      ('installation_id','operation_id','grant_id','principal_id','principal_kind','adopt_installation',
       'use_selector','use_actions','delegation_selector','delegation_actions','conditions','valid_from','expires_at','permanent','label'))
    OR request->'adopt_installation' IS DISTINCT FROM 'true'::jsonb
  THEN RAISE EXCEPTION 'invalid bounded management bootstrap request' USING ERRCODE='22023'; END IF;
  installation:=(request->>'installation_id')::uuid; operation:=(request->>'operation_id')::uuid;
  grant_identity:=(request->>'grant_id')::uuid; principal:=(request->>'principal_id')::uuid;
  principal_kind:=request->>'principal_kind';
  IF installation IS NULL OR operation IS NULL OR grant_identity IS NULL OR principal IS NULL
    OR '00000000-0000-0000-0000-000000000000'::uuid=ANY(ARRAY[installation,operation,grant_identity,principal])
    OR coalesce(principal_kind,'') NOT IN ('HUMAN','SERVICE') THEN RAISE EXCEPTION 'explicit bootstrap identities required' USING ERRCODE='22023'; END IF;
  SELECT oid INTO caller_oid FROM pg_catalog.pg_roles WHERE rolname=session_user AND rolcanlogin
    AND NOT (rolsuper OR rolcreatedb OR rolcreaterole OR rolreplication OR rolbypassrls);
  IF caller_oid IS NULL OR NOT pg_catalog.pg_has_role(caller_oid,'aegaeon_management_bootstrap','USAGE')
    OR NOT EXISTS(SELECT FROM management_authority.bootstrap_credentials c
      WHERE c.installation_id=installation AND c.role_oid=caller_oid AND c.role_name=session_user AND c.enabled FOR SHARE)
  THEN RAISE EXCEPTION 'dedicated selected-installation bootstrap credential required' USING ERRCODE='42501'; END IF;
  PERFORM FROM management_authority.installation i WHERE i.id=installation FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'selected installation does not match' USING ERRCODE='42501'; END IF;
  request_hash:=pg_catalog.sha256(pg_catalog.convert_to(request::text,'UTF8'));
  SELECT * INTO receipt FROM management_authority.operation_receipts WHERE operation_id=operation;
  IF FOUND THEN
    IF receipt.installation_id<>installation OR receipt.caller_role_oid<>caller_oid OR receipt.caller_role_name<>session_user
      OR receipt.canonical_sha256<>request_hash THEN RAISE EXCEPTION 'bootstrap receipt conflicts' USING ERRCODE='23505'; END IF;
    RETURN receipt.result;
  END IF;
  IF NOT EXISTS(SELECT FROM aegaeon.administrators a WHERE a.id=principal AND a.kind::text=principal_kind AND a.status='ACTIVE')
    THEN RAISE EXCEPTION 'exact active management principal required' USING ERRCODE='22023'; END IF;
  conditions:=coalesce(request->'conditions','{}'::jsonb);
  -- Validate condition syntax independently of a session; bootstrap never creates
  -- an authentication session or unbounded authentication evidence.
  IF pg_catalog.jsonb_typeof(conditions) IS DISTINCT FROM 'object'
    OR EXISTS(SELECT FROM pg_catalog.jsonb_object_keys(conditions) key WHERE key NOT IN ('credential_kind','credential_id','maximum_authentication_age_seconds'))
    OR (conditions ? 'credential_kind' AND conditions->>'credential_kind' NOT IN ('HUMAN','SERVICE'))
    OR (conditions ? 'credential_id' AND ((conditions->>'credential_id')::uuid IS NULL))
    OR (conditions ? 'maximum_authentication_age_seconds' AND
      (pg_catalog.jsonb_typeof(conditions->'maximum_authentication_age_seconds')<>'number'
       OR (conditions->>'maximum_authentication_age_seconds') !~ '^[0-9]{1,10}$'
       OR (conditions->>'maximum_authentication_age_seconds')::numeric>2147483647))
    THEN RAISE EXCEPTION 'invalid management grant conditions' USING ERRCODE='22023'; END IF;
  starts:=(request->>'valid_from')::timestamptz; ends:=(request->>'expires_at')::timestamptz;
  IF coalesce(request->'permanent','null'::jsonb) NOT IN ('true'::jsonb,'false'::jsonb) OR starts IS NULL THEN
    RAISE EXCEPTION 'explicit grant validity required' USING ERRCODE='22023'; END IF;
  forever:=(request->>'permanent')::boolean;
  use_actions:=management_authority.checked_actions_v1(request->'use_actions');
  IF request ? 'delegation_selector' OR request ? 'delegation_actions' THEN
    delegation_actions:=management_authority.checked_actions_v1(request->'delegation_actions');
    delegation_selector:=management_authority.prepare_selector_v1(installation,request->'delegation_selector');
  END IF;
  use_selector:=management_authority.prepare_selector_v1(installation,request->'use_selector');
  INSERT INTO management_authority.principals(installation_id,administrator_id,kind) VALUES(installation,principal,principal_kind)
    ON CONFLICT(installation_id,administrator_id) DO NOTHING;
  result:=pg_catalog.jsonb_build_object('operationId',operation,'grantId',grant_identity,'revision',1,'delegationEpoch',1);
  INSERT INTO management_authority.operation_receipts(operation_id,installation_id,caller_role_oid,caller_role_name,canonical_sha256,result)
    VALUES(operation,installation,caller_oid,session_user,request_hash,result);
  INSERT INTO management_authority.grants(id,installation_id,principal_id,principal_kind,bootstrap_operation_id,
    use_selector_id,use_action_policy,use_actions,delegation_selector_id,delegation_action_policy,delegation_actions,
    acknowledged_registry_version,conditions,valid_from,expires_at,permanent,label)
  VALUES(grant_identity,installation,principal,principal_kind,operation,use_selector,request->'use_actions'->>'policy',use_actions,
    delegation_selector,request->'delegation_actions'->>'policy',delegation_actions,1,conditions,starts,ends,forever,coalesce(request->>'label',''));
  INSERT INTO management_authority.audit_events(installation_id,operation_id,grant_id,actor_role_name,event_type,revision,delegation_epoch,acknowledged_registry_version)
    VALUES(installation,operation,grant_identity,session_user,'root_grant_issued',1,1,1);
  UPDATE management_authority.installation i SET adopted_at=pg_catalog.statement_timestamp() WHERE i.id=installation AND i.adopted_at IS NULL;
  RETURN result;
END
$function$;

CREATE FUNCTION management_authority.current_team_v1(selected_installation uuid,selected_kind text,selected_resource uuid)
RETURNS uuid LANGUAGE sql STABLE SET search_path=pg_catalog,management_authority,pg_temp
AS $function$
WITH RECURSIVE path AS (
  SELECT r.*,0 depth FROM management_authority.current_resources r
    WHERE r.installation_id=selected_installation AND r.resource_kind=selected_kind AND r.resource_id=selected_resource
  UNION ALL
  SELECT r.*,p.depth+1 FROM path p JOIN management_authority.current_resources r
    ON r.installation_id=p.installation_id AND r.resource_kind=p.parent_kind AND r.resource_id=p.parent_id WHERE p.depth<4
) SELECT resource_id FROM path WHERE resource_kind='team'
  AND EXISTS(SELECT FROM path WHERE resource_kind='installation' AND resource_id=selected_installation);
$function$;

-- Fixed-length comparison without a data-dependent early exit. It is a local
-- authentication implementation boundary, not a physical constant-time claim.
CREATE FUNCTION management_authority.mac_equal_v1(left_mac bytea,right_mac bytea) RETURNS boolean
LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,pg_temp
AS $function$
DECLARE difference integer:=0; position integer;
BEGIN
  IF pg_catalog.octet_length(left_mac) IS DISTINCT FROM 32 OR pg_catalog.octet_length(right_mac) IS DISTINCT FROM 32 THEN RETURN false; END IF;
  FOR position IN 0..31 LOOP
    difference:=difference | (pg_catalog.get_byte(left_mac,position) # pg_catalog.get_byte(right_mac,position));
  END LOOP;
  RETURN difference=0;
END
$function$;

CREATE FUNCTION management_authority.check_serving_role_v1(runtime_name text) RETURNS void
LANGUAGE plpgsql STABLE SET search_path=pg_catalog,management_authority,pg_temp
AS $function$
DECLARE actor oid; reachable oid; object oid;
BEGIN
  SELECT oid INTO actor FROM pg_catalog.pg_roles WHERE rolname=runtime_name AND rolcanlogin
    AND NOT (rolsuper OR rolcreatedb OR rolcreaterole OR rolreplication OR rolbypassrls);
  IF actor IS NULL OR pg_catalog.pg_has_role(actor,'aegaeon_management_authority_owner','MEMBER')
    OR pg_catalog.pg_has_role(actor,'aegaeon_management_bootstrap','MEMBER')
    THEN RAISE EXCEPTION 'management serving identity has administrative authority' USING ERRCODE='42501'; END IF;
  FOR reachable IN SELECT oid FROM pg_catalog.pg_roles r
      WHERE pg_catalog.pg_has_role(actor,r.oid,'USAGE') OR pg_catalog.pg_has_role(actor,r.oid,'SET') LOOP
    IF EXISTS(SELECT FROM pg_catalog.pg_roles r WHERE r.oid=reachable
      AND (r.rolsuper OR r.rolcreatedb OR r.rolcreaterole OR r.rolreplication OR r.rolbypassrls))
      OR pg_catalog.has_schema_privilege(reachable,'management_authority','CREATE')
      OR EXISTS(SELECT FROM pg_catalog.pg_database WHERE datname=current_database() AND datdba=reachable)
      THEN RAISE EXCEPTION 'management serving identity can assume administration' USING ERRCODE='42501'; END IF;
    FOR object IN SELECT c.oid FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace
        WHERE n.nspname='management_authority' AND c.relkind IN ('r','p','v') LOOP
      IF pg_catalog.has_table_privilege(reachable,object,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER,MAINTAIN')
        OR pg_catalog.has_any_column_privilege(reachable,object,'SELECT,INSERT,UPDATE,REFERENCES')
        THEN RAISE EXCEPTION 'management serving identity has direct authority storage access' USING ERRCODE='42501'; END IF;
    END LOOP;
    FOR object IN SELECT p.oid FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace
        WHERE n.nspname='management_authority' AND p.oid<>'management_authority.inventory_v1(jsonb)'::regprocedure LOOP
      IF pg_catalog.has_function_privilege(reachable,object,'EXECUTE') THEN
        RAISE EXCEPTION 'management serving identity can execute a maintenance helper' USING ERRCODE='42501'; END IF;
    END LOOP;
  END LOOP;
END
$function$;

-- Authentication, live authority and filtered keyset pagination all use the
-- caller's one repeatable-read snapshot. No credential bytes enter the result.
CREATE FUNCTION management_authority.inventory_v1(request jsonb) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,management_authority,pg_temp
SET lock_timeout='5s' SET work_mem='4MB'
AS $function$
DECLARE installation uuid; selected_grant uuid; kind text; action text; page_size integer;
  proof jsonb; authentication jsonb; checked_at timestamptz:=pg_catalog.statement_timestamp();
  credential uuid; principal uuid; principal_kind text; authenticated_at timestamptz; expires_at timestamptz;
  capability_allowed boolean:=true; team_ceiling uuid; ttl bigint; signing_key bytea; chain jsonb; version text; query_binding jsonb;
  cursor_value text; cursor_body jsonb; after_id uuid; expected_mac bytea; supplied_mac bytea;
  rows jsonb; more boolean; next_cursor text; last_id uuid; cursor_expiry timestamptz; crypto_schema name;
BEGIN
  PERFORM management_authority.check_serving_role_v1(session_user);
  IF pg_catalog.current_setting('transaction_isolation') NOT IN ('repeatable read','serializable')
    OR pg_catalog.current_setting('statement_timeout')::interval NOT BETWEEN interval '1 millisecond' AND interval '30 seconds'
    OR pg_catalog.jsonb_typeof(request) IS DISTINCT FROM 'object' OR pg_catalog.octet_length(request::text)>8192
    OR EXISTS(SELECT FROM pg_catalog.jsonb_object_keys(request) key
      WHERE key NOT IN ('installation_id','grant_id','resource_kind','limit','cursor','credential'))
    THEN RAISE EXCEPTION 'invalid bounded inventory request' USING ERRCODE='22023'; END IF;
  installation:=(request->>'installation_id')::uuid; selected_grant:=(request->>'grant_id')::uuid;
  kind:=request->>'resource_kind'; page_size:=coalesce((request->>'limit')::integer,100);
  IF installation IS NULL OR selected_grant IS NULL OR page_size NOT BETWEEN 1 AND 200
    THEN RAISE EXCEPTION 'invalid inventory identities or page size' USING ERRCODE='22023'; END IF;
  SELECT action_id INTO action FROM management_authority.action_registry WHERE resource_kind=kind;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown inventory resource kind' USING ERRCODE='22023'; END IF;
  SELECT i.cursor_key INTO signing_key FROM management_authority.installation i WHERE i.id=installation AND i.adopted_at IS NOT NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'installation authority is unavailable' USING ERRCODE='PMA02'; END IF;
  proof:=request->'credential';
  IF pg_catalog.jsonb_typeof(proof) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'management credential required' USING ERRCODE='PMA01'; END IF;
  IF proof->>'kind'='HUMAN' THEN
    ttl:=(proof->>'session_ttl_seconds')::bigint;
    IF ttl IS NULL OR ttl NOT BETWEEN 1 AND 86400 OR pg_catalog.octet_length(proof->>'namespace') NOT BETWEEN 1 AND 256
      OR coalesce(proof->>'digest','') !~ '^[0-9a-f]{64}$'
      THEN RAISE EXCEPTION 'invalid session evidence' USING ERRCODE='PMA01'; END IF;
    SELECT session.administrator_id,a.kind::text,pg_catalog.to_timestamp(session.created_at_epoch_secs),
      least(session.expires_at,pg_catalog.to_timestamp(session.created_at_epoch_secs)+pg_catalog.make_interval(secs=>ttl::double precision)),
      pg_catalog.substr(pg_catalog.encode(session.token_digest,'hex'),1,32)::uuid
      INTO principal,principal_kind,authenticated_at,expires_at,credential
    FROM aegaeon.runtime_management_sessions session JOIN aegaeon.administrators a ON a.id=session.administrator_id
    WHERE session.namespace=proof->>'namespace' AND session.token_digest=pg_catalog.decode(proof->>'digest','hex')
      AND a.kind='HUMAN' AND a.status='ACTIVE';
  ELSIF proof->>'kind'='SERVICE' THEN
    IF coalesce(proof->>'digest','') !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'invalid API key evidence' USING ERRCODE='PMA01'; END IF;
    SELECT key.service_administrator_id,a.kind::text,checked_at,
      least(coalesce(key.expires_at,checked_at+interval '5 minutes'),checked_at+interval '5 minutes'),key.id,key.team_id,
      EXISTS(SELECT FROM aegaeon.api_key_capabilities cap WHERE cap.api_key_id=key.id AND cap.capability IN ('READ','TEAM_ADMINISTRATION'))
      INTO principal,principal_kind,authenticated_at,expires_at,credential,team_ceiling,capability_allowed
    FROM aegaeon.api_keys key JOIN aegaeon.administrators a ON a.id=key.service_administrator_id
    WHERE key.id=(proof->>'id')::uuid AND key.key_hash=pg_catalog.decode(proof->>'digest','hex') AND key.status='ACTIVE'
      AND a.kind='SERVICE' AND a.status='ACTIVE';
  ELSE RAISE EXCEPTION 'management credential kind required' USING ERRCODE='PMA01'; END IF;
  authentication:=pg_catalog.jsonb_build_object('principal_id',principal,'principal_kind',principal_kind,
    'credential_id',credential,'authenticated_at',authenticated_at,'expires_at',expires_at);
  IF principal IS NULL OR NOT management_authority.conditions_hold_v1('{}',authentication,checked_at)
    THEN RAISE EXCEPTION 'management credential is invalid or expired' USING ERRCODE='PMA01'; END IF;
  IF NOT capability_allowed THEN RAISE EXCEPTION 'API key capability does not authorize inventory' USING ERRCODE='PMA02'; END IF;
  SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('id',c.grant_id,'depth',c.depth,'selector',c.selector_id,
    'policy',c.action_policy,'actions',c.actions,'revision',c.revision,'epoch',c.delegation_epoch,
    'selector_state',s.state,'anchor_incarnation',s.anchor_incarnation) ORDER BY c.depth)
  INTO chain FROM management_authority.validated_chain_v1(selected_grant,installation,authentication,checked_at) c
    JOIN management_authority.selectors s ON s.id=c.selector_id;
  IF chain IS NULL OR EXISTS(SELECT FROM pg_catalog.jsonb_array_elements(chain) c
    WHERE c->>'selector_state'<>'active' OR NOT management_authority.action_covers_v1(c->>'policy',
      ARRAY(SELECT pg_catalog.jsonb_array_elements_text(c->'actions')),action))
    THEN RAISE EXCEPTION 'current management grant does not authorize inventory' USING ERRCODE='PMA02'; END IF;
  version:=pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(chain::text,'UTF8')),'hex');
  query_binding:=pg_catalog.jsonb_build_object('installation',installation,'principal',principal,'principal_kind',principal_kind,
    'credential',credential,'grant',selected_grant,'kind',kind,'action',action,'limit',page_size,'version',version,'team_ceiling',team_ceiling);
  SELECT n.nspname INTO crypto_schema FROM pg_catalog.pg_extension e
    JOIN pg_catalog.pg_namespace n ON n.oid=e.extnamespace WHERE e.extname='pgcrypto';
  IF crypto_schema IS NULL THEN
    RAISE EXCEPTION 'inventory cryptographic supplier is unavailable' USING ERRCODE='58000';
  END IF;
  cursor_value:=request->>'cursor';
  IF cursor_value IS NOT NULL THEN
    IF pg_catalog.octet_length(cursor_value)>4096 OR cursor_value !~ '^[0-9a-f]+[.][0-9a-f]{64}$'
      THEN RAISE EXCEPTION 'invalid inventory cursor' USING ERRCODE='22023'; END IF;
    cursor_body:=pg_catalog.convert_from(pg_catalog.decode(pg_catalog.split_part(cursor_value,'.',1),'hex'),'UTF8')::jsonb;
    supplied_mac:=pg_catalog.decode(pg_catalog.split_part(cursor_value,'.',2),'hex');
    EXECUTE pg_catalog.format('SELECT %I.hmac($1::bytea,$2::bytea,''sha256'')',crypto_schema)
      INTO expected_mac USING pg_catalog.convert_to(cursor_body::text,'UTF8'),signing_key;
    IF NOT management_authority.mac_equal_v1(supplied_mac,expected_mac)
      OR cursor_body->'query' IS DISTINCT FROM query_binding OR (cursor_body->>'expires_at')::timestamptz<=checked_at
      THEN RAISE EXCEPTION 'stale or mismatched inventory cursor' USING ERRCODE='22023'; END IF;
    after_id:=(cursor_body->>'after')::uuid;
    cursor_expiry:=(cursor_body->>'expires_at')::timestamptz;
    IF after_id IS NULL OR cursor_expiry IS NULL OR NOT pg_catalog.isfinite(cursor_expiry)
      THEN RAISE EXCEPTION 'invalid inventory cursor fields' USING ERRCODE='22023'; END IF;
  ELSE cursor_expiry:=least(expires_at,checked_at+interval '5 minutes'); END IF;
  SELECT coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('id',r.resource_id,'document',r.document) ORDER BY r.resource_id),'[]'::jsonb)
  INTO rows FROM (
    SELECT resource_id,document FROM management_authority.current_resources resource
    WHERE resource.installation_id=installation AND resource.resource_kind=kind AND (after_id IS NULL OR resource.resource_id>after_id)
      AND (team_ceiling IS NULL OR management_authority.current_team_v1(installation,kind,resource.resource_id)=team_ceiling)
      AND NOT EXISTS(SELECT FROM pg_catalog.jsonb_array_elements(chain) node
        WHERE NOT management_authority.selector_covers_v1((node->>'selector')::uuid,installation,kind,resource.resource_id))
    ORDER BY resource.resource_id LIMIT page_size+1
  ) r;
  more:=pg_catalog.jsonb_array_length(rows)>page_size;
  IF more THEN
    rows:=rows-page_size;
    last_id:=(rows->(page_size-1)->>'id')::uuid;
    cursor_body:=pg_catalog.jsonb_build_object('query',query_binding,'after',last_id,'expires_at',cursor_expiry);
    EXECUTE pg_catalog.format('SELECT %I.hmac($1::bytea,$2::bytea,''sha256'')',crypto_schema)
      INTO expected_mac USING pg_catalog.convert_to(cursor_body::text,'UTF8'),signing_key;
    next_cursor:=pg_catalog.encode(pg_catalog.convert_to(cursor_body::text,'UTF8'),'hex')||'.'||
      pg_catalog.encode(expected_mac,'hex');
  END IF;
  RETURN pg_catalog.jsonb_build_object('items',(SELECT coalesce(pg_catalog.jsonb_agg(item->'document'),'[]'::jsonb) FROM pg_catalog.jsonb_array_elements(rows) item),
    'pageInfo',pg_catalog.jsonb_build_object('hasNextPage',more,'endCursor',next_cursor));
END
$function$;

-- Install on the selected product tables as their migration owner. The trigger
-- records identity only; it confers neither use nor delegation authority.
RESET ROLE;
CREATE TRIGGER management_resource_identity AFTER INSERT OR UPDATE OF id OR DELETE ON aegaeon.teams
FOR EACH ROW EXECUTE FUNCTION management_authority.capture_resource_identity_v1('team');
CREATE TRIGGER management_resource_identity AFTER INSERT OR UPDATE OF id OR DELETE ON aegaeon.tenants
FOR EACH ROW EXECUTE FUNCTION management_authority.capture_resource_identity_v1('tenant');
CREATE TRIGGER management_resource_identity AFTER INSERT OR UPDATE OF id OR DELETE ON aegaeon.environments
FOR EACH ROW EXECUTE FUNCTION management_authority.capture_resource_identity_v1('environment');
CREATE TRIGGER management_resource_identity AFTER INSERT OR UPDATE OF id OR DELETE ON aegaeon.end_users
FOR EACH ROW EXECUTE FUNCTION management_authority.capture_resource_identity_v1('user');
SET LOCAL ROLE aegaeon_subject_owner;
CREATE TRIGGER management_resource_identity AFTER INSERT OR UPDATE OF id OR DELETE ON aegaeon.application_organizations
FOR EACH ROW EXECUTE FUNCTION management_authority.capture_resource_identity_v1('organization');
RESET ROLE;
CREATE TRIGGER management_principal_identity BEFORE UPDATE OF id,kind ON aegaeon.administrators
FOR EACH ROW EXECUTE FUNCTION management_authority.protect_administrator_identity_v1();
SET LOCAL ROLE aegaeon_management_authority_owner;
REVOKE EXECUTE ON FUNCTION management_authority.capture_resource_identity_v1() FROM aegaeon_subject_owner;
REVOKE USAGE ON SCHEMA management_authority FROM aegaeon_subject_owner;
REVOKE ALL ON ALL TABLES IN SCHEMA management_authority FROM PUBLIC;

REVOKE ALL ON ALL FUNCTIONS IN SCHEMA management_authority FROM PUBLIC;
DO $access$ BEGIN
  EXECUTE pg_catalog.format('REVOKE USAGE ON SCHEMA management_authority FROM %I',session_user);
END $access$;
RESET ROLE;





-- BEGIN MANAGEMENT CATALOG SUCCESSOR
GRANT CREATE ON SCHEMA aegaeon TO aegaeon_subject_owner;
SET LOCAL ROLE aegaeon_management_authority_owner;
GRANT USAGE ON SCHEMA management_authority TO aegaeon_subject_owner;
GRANT EXECUTE ON FUNCTION management_authority.check_serving_role_v1(text) TO aegaeon_subject_owner;
RESET ROLE;
DO $management_catalog$
BEGIN
SET LOCAL ROLE aegaeon_subject_owner;
EXECUTE $definition$
CREATE OR REPLACE FUNCTION aegaeon.organization_import_target_v1(
  scope_environment uuid, runtime_name text, collection text, lookup_keys jsonb
) RETURNS TABLE(row_key text, row_data text)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
SET timezone = 'UTC' SET datestyle = 'ISO, YMD'
AS $function$
DECLARE schema_hash text;
BEGIN
  PERFORM aegaeon.subject_history_maintenance_actor();
  IF scope_environment IS NULL OR scope_environment='00000000-0000-0000-0000-000000000000'
    OR runtime_name IS NULL OR octet_length(runtime_name) NOT BETWEEN 1 AND 63
    OR collection IS NULL OR collection NOT IN ('catalog','namespace','environment_dependency','domain','owners','subject_history','identities','client_dependencies','connection_dependencies','operators','organizations','targets')
    OR lookup_keys IS NULL OR jsonb_typeof(lookup_keys)<>'array'
    OR pg_catalog.pg_is_in_recovery()
    OR current_setting('transaction_isolation')<>'repeatable read'
    OR current_setting('transaction_read_only')<>'on' THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid import target request';
  END IF;
  IF jsonb_array_length(lookup_keys)>10
    OR EXISTS(SELECT FROM jsonb_array_elements(lookup_keys) k WHERE jsonb_typeof(k)<>'string' OR octet_length(k#>>'{}') NOT BETWEEN 1 AND 4096)
    OR (SELECT count(*) FROM jsonb_array_elements(lookup_keys))<>(SELECT count(DISTINCT k) FROM jsonb_array_elements(lookup_keys) k) THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid import target keys';
  END IF;
  IF collection IN ('catalog','namespace') THEN
    IF jsonb_array_length(lookup_keys)<>0 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='unexpected catalog keys'; END IF;
    schema_hash:=aegaeon.subject_history_preflight(runtime_name);
    IF collection='catalog' THEN
      RETURN QUERY SELECT c.row_key,c.row_text FROM aegaeon.subject_history_physical_catalog(runtime_name) c
        WHERE c.row_key LIKE 'function:%' OR c.row_key LIKE 'atlas_revision:%'
          OR (c.row_key LIKE 'role:%' AND c.row_text::jsonb->>'rolname' IN ('aegaeon_subject_owner','aegaeon_management_authority_owner'));
    ELSE
      RETURN QUERY SELECT n.environment_id::text,jsonb_build_object('environment_id',n.environment_id,'issuer_host',n.issuer_host,'origin',n.origin,'contract_version',n.contract_version,'receipt_id',a.receipt_id,'schema_sha256',schema_hash)::text
        FROM aegaeon.subject_ownership_namespaces n JOIN aegaeon.subject_ownership_adoptions a
          ON a.environment_id=n.environment_id AND a.kind=n.origin
        WHERE n.environment_id=scope_environment AND n.contract_version=1;
    END IF;
    RETURN;
  END IF;
  IF jsonb_array_length(lookup_keys)=0 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='missing target keys'; END IF;
  IF collection IN ('domain','environment_dependency','owners','identities','client_dependencies','connection_dependencies','operators','organizations') AND EXISTS(
    SELECT FROM jsonb_array_elements_text(lookup_keys) k WHERE k !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' OR k='00000000-0000-0000-0000-000000000000') THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid target object key';
  END IF;
  RETURN QUERY WITH keys AS (SELECT k AS key, CASE WHEN collection IN ('domain','environment_dependency','owners','identities','client_dependencies','connection_dependencies','operators','organizations') THEN k::uuid ELSE NULL END AS id FROM jsonb_array_elements_text(lookup_keys) k), rows AS (
    SELECT e.id::text AS key,to_jsonb(v) AS data FROM aegaeon.environments e CROSS JOIN LATERAL (
      SELECT e.id,e.issuer_host,e.issuer_url,e.status,e.active_configuration_version_id,e.organization_identity_policy,e.organization_identity_policy_revision
    ) v WHERE collection='environment_dependency' AND e.id=scope_environment AND e.id IN (SELECT id FROM keys)
    UNION ALL SELECT d.id::text,to_jsonb(d) FROM aegaeon.authorization_domains d
      WHERE collection='domain' AND (d.id IN (SELECT id FROM keys) OR (d.environment_id=scope_environment AND d.is_default))
    UNION ALL SELECT o.owner_id::text,to_jsonb(o)||jsonb_build_object('history_count',(SELECT count(*) FROM aegaeon.end_user_subject_reservations r WHERE r.owner_id=o.owner_id),'current_identity_present',EXISTS(SELECT FROM aegaeon.end_users u WHERE u.id=o.owner_id))
      FROM aegaeon.end_user_identity_owners o WHERE collection='owners' AND o.owner_id IN (SELECT id FROM keys)
    UNION ALL SELECT r.subject,to_jsonb(r) FROM aegaeon.end_user_subject_reservations r
      WHERE collection='subject_history' AND r.environment_id=scope_environment AND r.subject COLLATE "C" IN (SELECT key COLLATE "C" FROM keys)
    UNION ALL SELECT u.id::text,to_jsonb(v)||jsonb_build_object('active_credentials',(SELECT count(*) FROM aegaeon.end_user_password_credentials p WHERE p.end_user_id=u.id AND p.status='ACTIVE'),
      'compatible_credentials',(SELECT count(*) FROM aegaeon.end_user_password_credentials p WHERE p.end_user_id=u.id AND p.status='ACTIVE' AND octet_length(p.password_hash)=97 AND p.password_hash ~ '^\$argon2id\$v=19\$m=19456,t=2,p=1\$[A-Za-z0-9+/]{21}[AQgw]\$[A-Za-z0-9+/]{42}[AEIMQUYcgkosw048]$'))
      FROM aegaeon.end_users u CROSS JOIN LATERAL (
        SELECT u.id,u.environment_id,u.subject,u.status,u.created_at,u.updated_at,u.organization_identity_revision,u.organization_reauthentication_after
      ) v WHERE collection='identities' AND u.id IN (SELECT id FROM keys)
    UNION ALL SELECT c.id::text,to_jsonb(v) FROM aegaeon.clients c CROSS JOIN LATERAL (
      SELECT c.id,c.environment_id,c.configuration_version_id,c.client_identifier,c.client_type,c.status,c.deleted_at,c.allowed_grant_types,c.allowed_scopes,c.dpop_bound_access_tokens,c.token_endpoint_authentication_method
    ) v WHERE collection='client_dependencies' AND c.id IN (SELECT id FROM keys)
    UNION ALL SELECT k.id::text,jsonb_build_object('id',k.id,'environment_id',scope_environment,'present',c.id IS NOT NULL,'configuration',CASE WHEN c.id IS NULL THEN NULL ELSE jsonb_build_object('id',c.id,'environment_id',c.environment_id,'configuration_version_id',c.configuration_version_id,'connection_identifier',c.connection_identifier,'connection_type',c.connection_type,'issuer_url',c.issuer_url,'client_id',c.client_id,'client_auth_method',c.client_auth_method,'status',c.status,'deleted_at',c.deleted_at) END)
      FROM keys k LEFT JOIN aegaeon.connections c ON c.id=k.id WHERE collection='connection_dependencies'
    UNION ALL SELECT a.id::text,jsonb_build_object('id',a.id,'human_member',a.status='ACTIVE' AND a.kind='HUMAN' AND t.status='ACTIVE' AND n.status='ACTIVE' AND e.status='ACTIVE')
      FROM aegaeon.administrators a JOIN aegaeon.team_memberships m ON m.administrator_id=a.id
      JOIN aegaeon.teams t ON t.id=m.team_id JOIN aegaeon.tenants n ON n.team_id=t.id
      JOIN aegaeon.environments e ON e.tenant_id=n.id
      WHERE collection='operators' AND e.id=scope_environment AND a.id IN (SELECT id FROM keys)
    UNION ALL SELECT o.id::text,jsonb_build_object('id',o.id) FROM aegaeon.application_organizations o
      WHERE collection='organizations' AND o.id IN (SELECT id FROM keys)
    UNION ALL SELECT t.audience,jsonb_build_object('domain_id',t.domain_id) FROM aegaeon.authorization_domain_targets t
      WHERE collection='targets' AND t.environment_id=scope_environment AND t.audience COLLATE "C" IN (SELECT key COLLATE "C" FROM keys)
  ) SELECT r.key,CASE WHEN octet_length(r.data::text)<=262144 THEN r.data::text ELSE NULL END FROM rows r ORDER BY r.key COLLATE "C";
END
$function$;
$definition$;
EXECUTE $definition$
CREATE OR REPLACE FUNCTION aegaeon.subject_history_observed_physical()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
SELECT pg_catalog.jsonb_build_object(
'columns',(SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('schema',n.nspname,'relation',c.relname,'name',a.attname,'type',pg_catalog.format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'collation',co.collname,'default',pg_catalog.pg_get_expr(d.adbin,d.adrelid)) ORDER BY c.relname COLLATE "C",a.attnum) FROM pg_catalog.pg_attribute a JOIN pg_catalog.pg_class c ON c.oid=a.attrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_catalog.pg_collation co ON co.oid=a.attcollation LEFT JOIN pg_catalog.pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE (n.nspname='aegaeon' AND c.relname IN ('subject_ownership_namespaces','subject_ownership_adoptions','end_user_identity_owners','end_user_subject_reservations','end_users','end_user_password_credentials','end_user_profiles','user_attribute_sources','lti_registrations','lti_registration_revisions','lti_identifiers','lti_launch_intents','environments','authorization_domains','authorization_domain_targets','application_organizations','organization_role_definitions','organization_memberships','organization_authority_events','organization_authority_outbox','organization_authority_receipts','organization_operator_grants','organization_client_bindings','organization_invitations','organization_invitation_challenges','organization_identity_requests','organization_admin_access_grants','organization_import_operations','organization_creation_receipts','subject_history_restorations','subject_history_restoration_pages') OR n.nspname='management_authority') AND a.attnum>0 AND NOT a.attisdropped),
'constraints',(SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('schema',n.nspname,'relation',c.relname,'name',con.conname,'definition',pg_catalog.pg_get_constraintdef(con.oid,false),'validated',con.convalidated,'deferrable',con.condeferrable,'deferred',con.condeferred) ORDER BY c.relname COLLATE "C",con.conname COLLATE "C") FROM pg_catalog.pg_constraint con JOIN pg_catalog.pg_class c ON c.oid=con.conrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE (n.nspname='aegaeon' AND c.relname IN ('subject_ownership_namespaces','subject_ownership_adoptions','end_user_identity_owners','end_user_subject_reservations','end_users','end_user_password_credentials','end_user_profiles','user_attribute_sources','lti_registrations','lti_registration_revisions','lti_identifiers','lti_launch_intents','environments','authorization_domains','authorization_domain_targets','application_organizations','organization_role_definitions','organization_memberships','organization_authority_events','organization_authority_outbox','organization_authority_receipts','organization_operator_grants','organization_client_bindings','organization_invitations','organization_invitation_challenges','organization_identity_requests','organization_admin_access_grants','organization_import_operations','organization_creation_receipts','subject_history_restorations','subject_history_restoration_pages') OR n.nspname='management_authority')),
'triggers',(SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('schema',n.nspname,'relation',c.relname,'name',t.tgname,'type',t.tgtype,'function_schema',function_namespace.nspname,'function',p.proname,'enabled',t.tgenabled,'arguments',pg_catalog.encode(t.tgargs,'hex'),'qualifier',pg_catalog.pg_get_expr(t.tgqual,t.tgrelid),'function_sha256',pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(pg_catalog.pg_get_functiondef(p.oid),'UTF8')),'hex')) ORDER BY c.relname COLLATE "C",t.tgname COLLATE "C") FROM pg_catalog.pg_trigger t JOIN pg_catalog.pg_class c ON c.oid=t.tgrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace JOIN pg_catalog.pg_proc p ON p.oid=t.tgfoid JOIN pg_catalog.pg_namespace function_namespace ON function_namespace.oid=p.pronamespace WHERE (n.nspname='aegaeon' AND c.relname IN ('subject_ownership_namespaces','subject_ownership_adoptions','end_user_identity_owners','end_user_subject_reservations','end_users','end_user_password_credentials','end_user_profiles','user_attribute_sources','lti_registrations','lti_registration_revisions','lti_identifiers','lti_launch_intents','environments','authorization_domains','authorization_domain_targets','application_organizations','organization_role_definitions','organization_memberships','organization_authority_events','organization_authority_outbox','organization_authority_receipts','organization_operator_grants','organization_client_bindings','organization_invitations','organization_invitation_challenges','organization_identity_requests','organization_admin_access_grants','organization_import_operations','organization_creation_receipts','subject_history_restorations','subject_history_restoration_pages') OR n.nspname='management_authority') AND NOT t.tgisinternal),
'indexes',(SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('schema',n.nspname,'relation',c.relname,'name',ic.relname,'definition',pg_catalog.pg_get_indexdef(i.indexrelid),'unique',i.indisunique,'valid',i.indisvalid,'ready',i.indisready,'live',i.indislive,'immediate',i.indimmediate) ORDER BY c.relname COLLATE "C",ic.relname COLLATE "C") FROM pg_catalog.pg_index i JOIN pg_catalog.pg_class c ON c.oid=i.indrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace JOIN pg_catalog.pg_class ic ON ic.oid=i.indexrelid WHERE (n.nspname='aegaeon' AND c.relname IN ('authorization_domains','authorization_domain_targets','application_organizations','organization_role_definitions','organization_memberships','organization_authority_events','organization_authority_outbox','organization_authority_receipts','organization_operator_grants','organization_client_bindings','organization_invitations','organization_invitation_challenges','organization_identity_requests','organization_admin_access_grants','organization_import_operations','organization_creation_receipts','subject_history_restorations','subject_history_restoration_pages','user_attribute_sources','lti_registrations','lti_registration_revisions','lti_identifiers','lti_launch_intents') OR n.nspname='management_authority')),
'views',(SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('schema',n.nspname,'name',c.relname,'definition',pg_catalog.pg_get_viewdef(c.oid,false)) ORDER BY c.relname COLLATE "C") FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='management_authority' AND c.relkind='v')
);
$function$;
$definition$;
EXECUTE $definition$
CREATE OR REPLACE FUNCTION aegaeon.subject_history_physical_catalog(runtime_name text)
 RETURNS TABLE(row_key text, row_text text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
 WITH protected_relations AS (
   SELECT c.oid FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace
   WHERE n.nspname='aegaeon' AND c.relname IN ('environments','end_users','end_user_password_credentials','end_user_profiles','user_attribute_sources','lti_registrations','lti_registration_revisions','lti_identifiers','lti_launch_intents','audit_events',
      'subject_ownership_namespaces','subject_ownership_adoptions','end_user_identity_owners','end_user_subject_reservations','authorization_domains','authorization_domain_targets','application_organizations','organization_role_definitions','organization_memberships','organization_authority_events','organization_authority_outbox','organization_authority_receipts','organization_operator_grants','organization_client_bindings','organization_invitations','organization_invitation_challenges','organization_identity_requests','organization_admin_access_grants','organization_import_operations','organization_creation_receipts','subject_history_restorations','subject_history_restoration_pages')
   UNION SELECT c.oid FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='management_authority' AND c.relkind IN ('r','p','v')
   UNION SELECT relid FROM pg_catalog.pg_partition_tree('aegaeon.audit_events'::regclass)
   UNION SELECT c.oid FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE c.relname='atlas_schema_revisions' AND n.nspname IN ('public','aegaeon')
 ), rows(kind, key, value) AS (
   SELECT 'namespace', n.oid::text, pg_catalog.to_jsonb(n) FROM pg_catalog.pg_namespace n WHERE n.nspname='aegaeon'
   UNION ALL SELECT 'relation',c.oid::text,pg_catalog.jsonb_build_object(
      'oid',c.oid,'relname',c.relname,'relnamespace',c.relnamespace,'reltype',c.reltype,
      'relowner',c.relowner,'relkind',c.relkind,'relpersistence',c.relpersistence,
      'relispartition',c.relispartition,'relpartbound',c.relpartbound::text,
      'relrowsecurity',c.relrowsecurity,'relforcerowsecurity',c.relforcerowsecurity,
      'relreplident',c.relreplident,'relacl',c.relacl,'reloptions',c.reloptions)
      FROM pg_catalog.pg_class c WHERE c.oid IN (SELECT oid FROM protected_relations)
   UNION ALL SELECT 'column',a.attrelid::text||':'||a.attnum::text,pg_catalog.to_jsonb(a) FROM pg_catalog.pg_attribute a WHERE a.attrelid IN (SELECT oid FROM protected_relations) AND a.attnum>0
   UNION ALL SELECT 'default',d.oid::text,pg_catalog.to_jsonb(d)||pg_catalog.jsonb_build_object('expression',pg_catalog.pg_get_expr(d.adbin,d.adrelid)) FROM pg_catalog.pg_attrdef d WHERE d.adrelid IN (SELECT oid FROM protected_relations)
   UNION ALL SELECT 'type',t.oid::text,pg_catalog.to_jsonb(t) FROM pg_catalog.pg_type t WHERE t.oid IN (SELECT atttypid FROM pg_catalog.pg_attribute WHERE attrelid IN (SELECT oid FROM protected_relations))
   UNION ALL SELECT 'collation',c.oid::text,pg_catalog.to_jsonb(c) FROM pg_catalog.pg_collation c WHERE c.oid IN (SELECT attcollation FROM pg_catalog.pg_attribute WHERE attrelid IN (SELECT oid FROM protected_relations))
   UNION ALL SELECT 'constraint',c.oid::text,pg_catalog.to_jsonb(c)||pg_catalog.jsonb_build_object('definition',pg_catalog.pg_get_constraintdef(c.oid,true)) FROM pg_catalog.pg_constraint c WHERE c.conrelid IN (SELECT oid FROM protected_relations) OR c.confrelid IN (SELECT oid FROM protected_relations)
   UNION ALL SELECT 'index',i.indexrelid::text,pg_catalog.to_jsonb(i)||pg_catalog.jsonb_build_object('definition',pg_catalog.pg_get_indexdef(i.indexrelid)) FROM pg_catalog.pg_index i WHERE i.indrelid IN (SELECT oid FROM protected_relations)
   UNION ALL SELECT 'trigger',t.oid::text,pg_catalog.to_jsonb(t)||pg_catalog.jsonb_build_object('definition',pg_catalog.pg_get_triggerdef(t.oid,true)) FROM pg_catalog.pg_trigger t WHERE t.tgrelid IN (SELECT oid FROM protected_relations)
   UNION ALL SELECT 'partition',i.inhrelid::text||':'||i.inhparent::text,pg_catalog.to_jsonb(i) FROM pg_catalog.pg_inherits i WHERE i.inhrelid IN (SELECT oid FROM protected_relations)
   UNION ALL SELECT 'function',p.oid::text,pg_catalog.to_jsonb(p)||pg_catalog.jsonb_build_object('definition',pg_catalog.pg_get_functiondef(p.oid),'acl',
      (SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('grantee',COALESCE(r.rolname,'PUBLIC'),'privilege',a.privilege_type,'grantable',a.is_grantable) ORDER BY a.grantee,a.privilege_type)
       FROM pg_catalog.aclexplode(COALESCE(p.proacl,pg_catalog.acldefault('f',p.proowner))) a LEFT JOIN pg_catalog.pg_roles r ON r.oid=a.grantee)) FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='management_authority' OR n.nspname='aegaeon' AND (p.proname LIKE 'subject_history_%' OR p.proname LIKE 'subject_ownership_%' OR p.proname IN ('restore_subject_history_page_v1','organization_creation_record_v1','organization_import_hold_guard','organization_identity_guard','organization_identity_credential_guard','organization_identity_policy_guard','organization_identity_profile_guard','organization_support_policy_guard','organization_admin_access_guard','organization_snapshot_history_v1','organization_import_target_v1','organization_import_hold_guard','organization_import_prepared_rows_v1','organization_import_operation_v1','organization_import_begin_v1','organization_import_row_v1','organization_import_finish_v1') OR p.proname IN ('inventory_subject_ownership_history_v1','adopt_subject_ownership_history_v1','validate_subject_ownership_namespace_v1'))
   UNION ALL SELECT 'role',r.oid::text,pg_catalog.to_jsonb(r) FROM pg_catalog.pg_roles r
   UNION ALL SELECT 'membership',m.roleid::text||':'||m.member::text||':'||m.grantor::text,pg_catalog.to_jsonb(m) FROM pg_catalog.pg_auth_members m
   UNION ALL SELECT 'parameter_acl',p.oid::text,pg_catalog.to_jsonb(p) FROM pg_catalog.pg_parameter_acl p
   UNION ALL SELECT 'atlas_revision',r.row_key,r.row_text::jsonb FROM aegaeon.subject_history_revision_rows() r
   UNION ALL SELECT 'runtime_role',runtime_name,pg_catalog.jsonb_build_object('runtime_role',runtime_name)
 ) SELECT kind||':'||key, value::text FROM rows ORDER BY kind COLLATE "C",key COLLATE "C"
$function$;
$definition$;
EXECUTE $definition$
CREATE OR REPLACE FUNCTION aegaeon.subject_history_check_runtime_role(runtime_name text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE runtime_id oid; entry_id oid; reachable record; role_row record; relation_row record; schema_owner oid;
BEGIN
  SELECT * INTO role_row FROM pg_catalog.pg_roles WHERE rolname = runtime_name;
  IF NOT FOUND OR NOT role_row.rolcanlogin OR role_row.rolsuper OR role_row.rolcreatedb
     OR role_row.rolcreaterole OR role_row.rolreplication OR role_row.rolbypassrls THEN
    RAISE EXCEPTION 'subject runtime role is not a restricted login';
  END IF;
  entry_id := role_row.oid;
  IF pg_catalog.pg_has_role(entry_id,'aegaeon_subject_owner','MEMBER')
     OR pg_catalog.pg_has_role(entry_id,'aegaeon_subject_maintenance','MEMBER') THEN
    RAISE EXCEPTION 'subject runtime has protected group membership, including administrative authority';
  END IF;
  FOR reachable IN SELECT oid FROM pg_catalog.pg_roles r WHERE pg_catalog.pg_has_role(entry_id,r.oid,'USAGE') OR pg_catalog.pg_has_role(entry_id,r.oid,'SET') LOOP
  runtime_id := reachable.oid;
  FOR relation_row IN SELECT c.oid FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace
    WHERE n.nspname='aegaeon' AND c.relname IN ('subject_history_restorations','subject_history_restoration_pages') LOOP
    IF pg_catalog.has_table_privilege(runtime_id,relation_row.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER,MAINTAIN')
      OR pg_catalog.has_any_column_privilege(runtime_id,relation_row.oid,'SELECT,INSERT,UPDATE,REFERENCES') THEN
      RAISE EXCEPTION 'runtime has direct history restoration authority';
    END IF;
  END LOOP;
  IF pg_catalog.has_table_privilege(runtime_id,'aegaeon.organization_creation_receipts','INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER,MAINTAIN')
    OR pg_catalog.has_any_column_privilege(runtime_id,'aegaeon.organization_creation_receipts','INSERT,UPDATE,REFERENCES') THEN
    RAISE EXCEPTION 'runtime has direct creation receipt mutation authority';
  END IF;

  IF pg_catalog.has_schema_privilege(runtime_id, 'aegaeon', 'CREATE')
     OR pg_catalog.has_parameter_privilege(runtime_id, 'session_replication_role', 'SET') THEN
    RAISE EXCEPTION 'subject runtime can bypass protected schema guards';
  END IF;
  SELECT nspowner INTO schema_owner FROM pg_catalog.pg_namespace WHERE nspname = 'aegaeon';
  IF pg_catalog.pg_has_role(runtime_id, schema_owner, 'USAGE') OR pg_catalog.pg_has_role(runtime_id, schema_owner, 'SET') THEN
    RAISE EXCEPTION 'subject runtime can assume schema ownership';
  END IF;
  FOR role_row IN SELECT * FROM pg_catalog.pg_roles
      WHERE rolname IN ('aegaeon_subject_owner', 'aegaeon_subject_maintenance')
         OR rolsuper OR rolcreatedb OR rolcreaterole OR rolreplication OR rolbypassrls LOOP
    IF pg_catalog.pg_has_role(runtime_id, role_row.oid, 'USAGE') OR pg_catalog.pg_has_role(runtime_id, role_row.oid, 'SET') THEN
      RAISE EXCEPTION 'subject runtime can assume protected or administrative authority';
    END IF;
  END LOOP;
  FOR relation_row IN SELECT c.oid, c.relname, c.relowner FROM pg_catalog.pg_class c
      JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
      WHERE (n.nspname = 'aegaeon' AND c.relname IN ('environments', 'end_users','end_user_password_credentials','end_user_profiles','user_attribute_sources','lti_registrations','lti_registration_revisions','lti_identifiers','lti_launch_intents',
        'subject_ownership_namespaces', 'subject_ownership_adoptions',
        'end_user_identity_owners', 'end_user_subject_reservations','authorization_domains','authorization_domain_targets','application_organizations','organization_role_definitions','organization_memberships','organization_authority_events','organization_authority_outbox','organization_authority_receipts','organization_operator_grants','organization_client_bindings','organization_invitations','organization_invitation_challenges','organization_identity_requests','organization_admin_access_grants','organization_import_operations','organization_creation_receipts','subject_history_restorations','subject_history_restoration_pages'))
        OR (c.relname='atlas_schema_revisions' AND n.nspname IN ('public','aegaeon')) LOOP
    IF pg_catalog.pg_has_role(runtime_id, relation_row.relowner, 'USAGE')
       OR pg_catalog.pg_has_role(runtime_id, relation_row.relowner, 'SET') THEN
      RAISE EXCEPTION 'subject runtime can assume ownership of a guarded table';
    END IF;
    IF pg_catalog.has_table_privilege(runtime_id, relation_row.oid, 'TRIGGER') THEN
      RAISE EXCEPTION 'subject runtime can install competing identity triggers';
    END IF;
    IF relation_row.relname NOT IN ('environments', 'end_users','end_user_password_credentials','end_user_profiles','user_attribute_sources','lti_registrations','lti_registration_revisions','lti_identifiers','lti_launch_intents','authorization_domains','authorization_domain_targets','application_organizations','organization_role_definitions','organization_memberships','organization_authority_events','organization_authority_outbox','organization_authority_receipts','organization_operator_grants','organization_client_bindings','organization_invitations','organization_invitation_challenges','organization_identity_requests','organization_admin_access_grants','organization_import_operations','organization_creation_receipts')
       AND (pg_catalog.has_table_privilege(runtime_id, relation_row.oid, 'INSERT,UPDATE,DELETE,TRUNCATE,TRIGGER')
         OR pg_catalog.has_any_column_privilege(runtime_id, relation_row.oid, 'INSERT,UPDATE')) THEN
      RAISE EXCEPTION 'subject runtime has permanent authority mutation privileges';
    END IF;
  END LOOP;
  -- Relation OIDs include the parent, leaves and subpartitions in every schema.
  -- INSERT and SELECT are legitimate runtime audit operations; mutation is not.
  FOR relation_row IN SELECT c.oid,c.relowner
      FROM pg_catalog.pg_partition_tree('aegaeon.audit_events'::regclass) t
      JOIN pg_catalog.pg_class c ON c.oid=t.relid LOOP
    IF pg_catalog.pg_has_role(runtime_id,relation_row.relowner,'USAGE')
       OR pg_catalog.pg_has_role(runtime_id,relation_row.relowner,'SET')
       OR pg_catalog.has_table_privilege(runtime_id,relation_row.oid,'UPDATE,DELETE,TRUNCATE,TRIGGER')
       OR pg_catalog.has_any_column_privilege(runtime_id,relation_row.oid,'UPDATE') THEN
      RAISE EXCEPTION 'subject runtime can rewrite protected audit history';
    END IF;
  END LOOP;
  IF EXISTS (SELECT FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace
      WHERE n.nspname='aegaeon'
      AND (p.proname LIKE 'subject_history_%' OR p.proname IN
        ('organization_import_hold_guard','organization_identity_guard','organization_identity_credential_guard','organization_identity_policy_guard','organization_identity_profile_guard','organization_support_policy_guard','organization_admin_access_guard','subject_ownership_guard_user','subject_ownership_guard_environment','subject_ownership_immutable','subject_ownership_guard_insert',
         'inventory_subject_ownership_history_v1','adopt_subject_ownership_history_v1'))
      AND (pg_catalog.has_function_privilege(runtime_id, p.oid, 'EXECUTE')
        OR pg_catalog.pg_has_role(runtime_id,p.proowner,'USAGE') OR pg_catalog.pg_has_role(runtime_id,p.proowner,'SET'))) THEN
    RAISE EXCEPTION 'subject runtime can execute or own protected maintenance helpers';
  END IF;
  IF pg_catalog.has_table_privilege(runtime_id,'aegaeon.organization_identity_requests','UPDATE')
    OR EXISTS (SELECT FROM pg_catalog.pg_attribute a WHERE a.attrelid='aegaeon.organization_identity_requests'::regclass
      AND a.attnum>0 AND NOT a.attisdropped
      AND a.attname NOT IN ('state','result','delivery_revision','delivered_at','delivery_outcome','capability_hash')
      AND pg_catalog.has_column_privilege(runtime_id,a.attrelid,a.attnum,'UPDATE')) THEN
    RAISE EXCEPTION 'runtime can rewrite identity request bindings';
  END IF;
  -- History deletion and identity replacement are not runtime operations.
  FOR relation_row IN SELECT c.oid,c.relname FROM pg_catalog.pg_class c
      JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace
      WHERE n.nspname='aegaeon' AND c.relname IN ('authorization_domains','authorization_domain_targets','application_organizations','organization_role_definitions','organization_memberships','organization_authority_events','organization_authority_outbox','organization_authority_receipts','organization_operator_grants','organization_client_bindings','organization_invitations','organization_invitation_challenges','organization_identity_requests','organization_admin_access_grants','organization_import_operations','organization_creation_receipts','subject_history_restorations','subject_history_restoration_pages') LOOP
    IF pg_catalog.has_table_privilege(runtime_id,relation_row.oid,'DELETE,TRUNCATE,REFERENCES')
       OR pg_catalog.has_any_column_privilege(runtime_id,relation_row.oid,'REFERENCES') THEN
      RAISE EXCEPTION 'organization runtime can delete or redefine authority history';
    END IF;
    IF EXISTS (SELECT FROM pg_catalog.pg_attribute a WHERE a.attrelid=relation_row.oid
        AND a.attnum>0 AND NOT a.attisdropped
        AND a.attname<>ALL(CASE relation_row.relname
        WHEN 'organization_invitations' THEN ARRAY['state','revision','delivery_revision','delivered_at','capability_hash','accepted_challenge_id','result','delivery_outcome']::text[]
        WHEN 'organization_invitation_challenges' THEN ARRAY['delivery_revision','delivered_at','capability_hash','delivery_outcome']::text[]
        WHEN 'organization_identity_requests' THEN ARRAY['state','result','delivery_revision','delivered_at','capability_hash','delivery_outcome']::text[]
        WHEN 'organization_client_bindings' THEN ARRAY['active','revision','targets']::text[]
        WHEN 'organization_operator_grants' THEN ARRAY['active','revision','capabilities']::text[]
        WHEN 'organization_admin_access_grants' THEN ARRAY['active','revision','revocation_key','revocation_digest']::text[]
        WHEN 'authorization_domains' THEN ARRAY['name','is_default','enabled','revision','invitation_delivery','support_policy','support_policy_revision']::text[]
        WHEN 'authorization_domain_targets' THEN ARRAY['domain_id','management','introspection_clients']::text[]
        WHEN 'application_organizations' THEN ARRAY['state','revision','grant_generation']::text[]
        WHEN 'organization_role_definitions' THEN ARRAY['version','privileges','manages_members','assignable_roles']::text[]
        WHEN 'organization_memberships' THEN ARRAY['state','revision','grant_generation','roles']::text[]
        WHEN 'organization_authority_outbox' THEN ARRAY['delivered_at','attempts']::text[]
        ELSE ARRAY[]::text[] END)
        AND pg_catalog.has_column_privilege(runtime_id,relation_row.oid,a.attnum,'UPDATE')) THEN
      RAISE EXCEPTION 'organization runtime can replace identity or rewrite immutable records';
    END IF;
  END LOOP;
  END LOOP;
  PERFORM management_authority.check_serving_role_v1(runtime_name);
END
$function$;
$definition$;
EXECUTE $definition$
CREATE OR REPLACE FUNCTION aegaeon.subject_history_preflight(runtime_name text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
